(53, 'Penyaluran Bantuan kepada Mustahik Asnaf Kesehatan', 'penyaluran-bantuan-kepada-mustahik-asnaf-kesehatan', '<p><img src=\"http://localhost/blackexpomediaonline/asset/images/Gambar_WhatsApp_2025-10-31_pukul_10_26_32_3e1db411.jpg\" style=\"width: 100%;\"><br></p>', 'ALBUM_BFOTO_BAZNAS_SEHAT.jpg', 'Y', 46, '2025-11-01', '10:55:51', 'Sabtu', 'admin'),
(51, 'Sosialisasi BAZNAS Kabupaten Sumbawa di Dinas Perhubungan', 'sosialisasi-baznas-kabupaten-sumbawa-di-dinas-perhubungan', '<p>Sosialisasi BAZNAS Kabupaten Sumbawa merupakan kegiatan penguatan pengumpulan Zakat, Infak dan sedekah yang ditargetkan kepada Dinas/Instansi, BUMD, BUMN Dikabupaten Sumbawa termasuk muzaki perorangan.</p>\r\n', 'ALBUM_BFOTO.jpg', 'Y', 105, '2018-04-21', '22:55:11', 'Sabtu', 'admin'),
(54, 'Sosialisasi ZIS di Aula SMPN 1 Sumbawa', 'sosialisasi-zis-di-aula-smpn-1-sumbawa', '', 'IMG-20251027-WA0019.jpg', 'Y', 58, '2025-11-04', '12:44:08', 'Selasa', 'admin'),
(55, 'Penyaluran Bantuan ZIS BAZNAS 2.100.000.000 Di halaman kantor bupati sumbawa', 'penyaluran-bantuan-zis-baznas-2100000000-di-halaman-kantor-bupati-sumbawa', '', 'IMG-20251108-WA0097.jpg', 'Y', 68, '2025-11-08', '09:52:21', 'Sabtu', 'admin'),
(56, 'Penyerahan Bantuan Masjid Al-Munawwarah dan Santunan untuk Imam dan Marbot', 'penyerahan-bantuan-masjid-almunawwarah-dan-santunan-untuk-imam-dan-marbot', '<p><br></p>', '5.jpg', 'Y', 49, '2025-11-09', '18:19:24', 'Minggu', 'admin'),
