(58, 'Ucapan Selamat atas Pelantikan Pimpinan BAZNAS Kabupaten Sumbawa Peride 2025-2030 oleh Ketua BAZNAS ', 'ucapan-selamat-atas-pelantikan-pimpinan-baznas-kabupaten-sumbawa-peride-20252030-oleh-ketua-baznas-r', '<p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/baznas_ri_2.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/baznas_ri_1.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/baznas_ri_3.jpg\" style=\"width: 50%;\"><br></p>', 'surat_dari_baznas_RI_1.jpg', 'Y', 45, '2025-11-19', '11:19:26', 'Rabu', 'admin'),
(59, 'Milad Muhammadiyah Ke-113', 'milad-muhammadiyah-ke113', '<p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/milad_muhammadiyah_1131.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \">Segenap Pimpinan dan Staf Pelaksana Badan Amil Zakat Nasional (BAZNAS) Kabupaten Sumbawa Mengucapkan Selamat Memperingati MIlad Muhammadiyah Ke-113! Semoga Allah SWT senantiasa membimbing dan memberkahi langkah-langkah kebaikan kita semua. Mari kita terus berjuang dalam kebaikan dan meningkatkan ukhuwah Islamiyah.&nbsp;</p>', 'milad_muhammadiyah_113.jpg', 'Y', 43, '2025-11-19', '13:59:43', 'Rabu', 'admin'),
(60, 'BAZNAS Sumbawa Hadiri Rakorda BAZNAS se-NTB tahun 2025', 'baznas-sumbawa-hadiri-rakorda-baznas-sentb-tahun-2025', '<p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/btb_edit.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/rakorda3.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/rakorda2.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/rakorda11.jpg\" style=\"width: 50%;\"><br></p>', 'rakorcopy.jpg', 'Y', 98, '2025-12-10', '21:02:04', 'Rabu', 'admin'),
(61, 'Ngabar BAZNAS (Ngaji Bareng BAZNAS) dan Pembagian Bantuan Kesehatan, Bantuan MAHYANI, Bantuan Geroba', 'ngabar-baznas-ngaji-bareng-baznas-dan-pembagian-bantuan-kesehatan-bantuan-mahyani-bantuan-gerobak-da', '<p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/14_nov.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/14_nov5.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/14_nov4.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/14_nov3.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/14nov.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/1411.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br><img src=\"https://baznassumbawa.id/asset/images/141.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/14n.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/14no.jpg\" style=\"width: 50%;\"><br></p>', '14_nov6.jpg', 'Y', 23, '2025-12-24', '09:37:54', 'Rabu', 'admin'),
(62, 'Silaturrahim Ketua BAZNAS Provinsi NTB Dengan Pimpinan  BAZNAS Kab. Sumbawa', 'silaturrahim-ketua-baznas-provinsi-ntb-dengan-pimpinan--baznas-kab-sumbawa', '<p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/58e009c6-b5af-42bd-95db-dd54cd83a706.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/silaturrahmi_ka_baznas_prov.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/silaturahmi_baznas_prov.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/silaturahmi_ketua_baznas_prov.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/silaturrahmi_ketua_bazns_prov.jpg\" style=\"width: 50%;\"><br></p>', 'silaturrahmi_ketua_baznas_provinsi.jpg', 'Y', 29, '2025-12-29', '11:29:10', 'Senin', 'admin'),
(63, 'Silaturrahim Pengurus BAZNAS Kab. Sumbawa Bersama IKASUM JAYA (Ikatan Keluarga Sumbawa Jabodetabek)', 'silaturrahim-pengurus-baznas-kab-sumbawa-bersama-ikasum-jaya-ikatan-keluarga-sumbawa-jabodetabek', '<p style=\"text-align: center;\"><img src=\"https://baznassumbawa.id/asset/images/ikasum_3_edit1.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center;\"><img src=\"https://baznassumbawa.id/asset/images/ikasum_2_edit1.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center;\"><img src=\"https://baznassumbawa.id/asset/images/ikasum_1_edit1.jpg\" style=\"width: 50%;\"><br></p>', 'ikasum_1_edit.jpg', 'Y', 22, '2025-12-29', '11:44:15', 'Senin', 'admin'),
(64, 'Silaturrahim Pengurus BAZNAS Kab. Sumbawa dengan YM Sultan Muhammad Kaharuddin IV', 'silaturrahim-pengurus-baznas-kab-sumbawa-dengan-ym-sultan-muhammad-kaharuddin-iv', '<p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/sultan_2_edit.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/sultan_1_edit1.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/sultan_3_edit1.jpg\" style=\"width: 50%;\"><br></p>', 'sultan_1_edit.jpg', 'Y', 24, '2025-12-29', '12:06:34', 'Senin', 'admin'),
(65, 'Kado Spesial BAZNAS Sumbawa di hari jadi ke 67 Kabupaten Sumbawa', 'kado-spesial-baznas-sumbawa-di-hari-jadi-ke-67-kabupaten-sumbawa', '<p>Pendistribusian dana zakat untuk 1000 mustahik</p><p><img src=\"https://baznassumbawa.id/asset/images/simbolis1.jpg\" style=\"width: 50%;\"><img src=\"https://baznassumbawa.id/asset/images/boss1.jpg\" style=\"width: 50%;\"><br><img src=\"https://baznassumbawa.id/asset/images/COVER.jpg\" style=\"width: 50%;\"><img src=\"https://baznassumbawa.id/asset/images/KURSI_RODA.jpg\" style=\"width: 50%;\"><img src=\"https://baznassumbawa.id/asset/images/WAWANCARA.jpg\" style=\"width: 50%;\"><img src=\"https://baznassumbawa.id/asset/images/FULL.jpg\" style=\"width: 50%;\"><img src=\"https://baznassumbawa.id/asset/images/ASFZXFA.jpg\" style=\"width: 50%;\"><img src=\"https://baznassumbawa.id/asset/images/FZFDFA.jpg\" style=\"width: 50%;\"><img src=\"https://baznassumbawa.id/asset/images/BFDSAD.jpg\" style=\"width: 50%;\"><img src=\"https://baznassumbawa.id/asset/images/FHJFVB.jpg\" style=\"width: 50%;\"></p>', 'cover_1000_mustahik.jpg', 'Y', 72, '2026-01-21', '09:52:14', 'Rabu', 'admin'),
(67, 'Sosialisasi Gerakan Gemar Berzakat, Berinfak, Bersedekah dan Optimalisasi Satu QRIS untuk Semua deng', 'sosialisasi-gerakan-gemar-berzakat-berinfak-bersedekah-dan-optimalisasi-satu-qris-untuk-semua-deng', '<p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/WhatsApp_Image_2026-02-04_at_16_06_25.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/WhatsApp_Image_2026-02-04_at_14_55_08.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/pgrii.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/pgri.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/WhatsApp_Image_2026-02-04_at_20_11_00.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/IMG-20260204-WA0280.jpg\" style=\"width: 50%;\"><span style=\"font-family: Tahoma;\"><br></span></p><p style=\"text-align: center; \"><span style=\"font-family: Tahoma;\"><br></span></p><p style=\"text-align: center; \"><span style=\"font-family: Tahoma;\"><br></span></p><p style=\"text-align: center; \"><span style=\"font-family: Tahoma;\">?</span><img src=\"https://baznassumbawa.id/asset/images/IMG-20260204-WA0286.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/WhatsApp_Image_2026-02-05_at_08_36_33.jpg\" style=\"width: 50%;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/dikbud.jpg\" style=\"wi