(68, 'QRIS BAZNAS KABUPATEN SUMBAWA UNTUK REKENING ZAKAT DAN INFAK', 'qris-baznas-kabupaten-sumbawa-untuk-rekening-zakat-dan-infak', '<p style=\"text-align: center; \"><span style=\"font-family: &quot;Arial Black&quot;;\">QRIS ZAKAT MELALUI REKENING BAZNAS KABUPATEN SUMBAWA</span></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/WhatsApp_Image_2026-02-05_at_10_44_59_(1).jpg\" style=\"width: 100%;\"></p><p style=\"text-align: center; \">QRIS INFAK MELALUI REKENING BAZNAS KABUPATEN SUMBAWA</p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/WhatsApp_Image_2026-02-05_at_10_44_59.jpg\" style=\"width: 100%;\"><br></p>', 'WhatsApp_Image_2026-02-05_at_10_44_59_(1).jpg', 'Y', 16, '2026-02-05', '09:49:19', 'Kamis', 'admin'),
(69, 'Sosialisasi Implementasi Regulasi Terkait Pengelolaan ZIS (Zakat, Infak, dan Sedekah) dan Optimalisa', 'sosialisasi-implementasi-regulasi-terkait-pengelolaan-zis-zakat-infak-dan-sedekah-dan-optimalisa', '<p><img src=\"https://baznassumbawa.id/asset/images/bupati2.jpg\" style=\"width: 708px;\"><img src=\"https://baznassumbawa.id/asset/images/ketua.jpg\" style=\"width: 708px;\"><img src=\"https://baznassumbawa.id/asset/images/02488e67-ee07-4715-b4c3-3920f20b54ca.jpg\" style=\"font-size: 1rem; width: 982.39px;\"></p><p><br></p><p><img src=\"https://baznassumbawa.id/asset/images/8e4c03d6-ce58-4da6-bb69-584b5a697723.jpg\" style=\"width: 952.406px;\"></p><p><br></p><p><img src=\"https://baznassumbawa.id/asset/images/17384bc4-7819-47f5-9c02-b1e1086997f9.jpg\" style=\"width: 967.391px;\"></p><p><br></p><p><img src=\"https://baznassumbawa.id/asset/images/1140db55-fbe4-43eb-bfba-b0b47ab89d6b.jpg\" style=\"width: 997.38px;\"></p><p><br></p><p><img src=\"https://baznassumbawa.id/asset/images/f80f7656-27da-4c87-8913-4de65e58170c.jpg\" style=\"width: 1012.38px;\"></p><p><br></p><p><img src=\"https://baznassumbawa.id/asset/images/qris.jpg\" style=\"width: 100%;\"></p><p><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/bupati21.jpg\" style=\"width: 708px;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/ketua1.jpg\" style=\"width: 708px;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/waka_4.jpg\" style=\"width: 708px;\"></p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \"><img src=\"https://baznassumbawa.id/asset/images/peserta1.jpg\" style=\"width: 1027.38px;\"><br></p>', '02488e67-ee07-4715-b4c3-3920f20b54ca.jpg', 'Y', 4, '2026-02-12', '08:49:41', 'Kamis', 'admin');
