INSERT INTO `berita` (`id_berita`, `id_kategori`, `username`, `judul`, `sub_judul`, `youtube`, `judul_seo`, `headline`, `aktif`, `utama`, `isi_berita`, `keterangan_gambar`, `hari`, `tanggal`, `jam`, `gambar`, `dibaca`, `tag`, `status`) VALUES
(709, 75, 'admin', 'Wabup Ingatkan Pentingnya Sinergi dan Kolaborasi', 'Pentingnya sinergitas dan kolaborasi Lintas OPD', '', 'wabup-ingatkan-pentingnya-sinergi-dan-kolaborasi', 'N', 'Y', 'Y', '<p style=\"color: rgb(33, 37, 41);\">Ketika menerima kunjungan pimpinan BAZNAS Kabupaten Sumbawa di pendopo Wabup, Jum\'at lalu (24/10), Wabup Drs. Muhammad Anshori mengingatkan pentingnya sinergi dan kolaborasi antara Pemerintah Daerah dengan BAZNAS.</p><p style=\"color: rgb(33, 37, 41);\">Menurut wabup, tujuan inti pembangunan daerah adalah untuk mengentaskan kemiskinan dan mewujudkan kesejahteraan masyarakat. Oleh karena itu perlu sinergi dan kolaborasi semua pihak, sehingga pelaksanaan pembangunan bisa tepat sasaran. </p><p style=\"color: rgb(33, 37, 41);\">Wabup berharap BAZNAS benar benar mengarahkan progamnya sesuai ketentuan syariat dan regulasi yang berlaku.</p><p style=\"color: rgb(33, 37, 41);\">Dalam konteks memaksimalkan pengumpulan zakat dan infak, wabup menyarankan pendekatan yang lebih efektif, baik secara kelembagaan maupun perorangan.</p>', '', 'Kamis', '2025-10-30', '22:59:52', 'AD90B16E-4715-4592-850A-D01C08A80A20.png', 39, 'berita-dan-kegiatan', 'Y'),
(710, 67, 'admin', 'Jemput Zakat BAZNAS Kabupaten Sumbawa', '', '', 'jemput-zakat-baznas-kabupaten-sumbawa', 'N', 'Y', 'N', '<article class=\"artikel-zakat\">\r\n  <header>\r\n    <h1><span style=\"color: inherit; font-family: inherit; font-size: 2rem;\">Daftar Isi</span></h1></header><nav class=\"toc\">\r\n    <ul>\r\n      <li><a href=\"#tentang\">Tentang Layanan Jemput Zakat</a></li>\r\n      <li><a href=\"#tujuan\">Tujuan Program</a></li>\r\n      <li><a href=\"#cara\">Cara Menggunakan Layanan</a></li>\r\n      <li><a href=\"#jenis\">Jenis Zakat yang Dapat Dijemput</a></li>\r\n      <li><a href=\"#keuntungan\">Keuntungan Layanan</a></li>\r\n      <li><a href=\"#wilayah\">Wilayah Layanan</a></li>\r\n      <li><a href=\"#kontak\">Kontak dan Informasi</a></li>\r\n    </ul>\r\n  </nav>\r\n\r\n  <section id=\"tentang\">\r\n    <h2>Tentang Layanan Jemput Zakat</h2>\r\n    <p>\r\n      BAZNAS Kabupaten Sumbawa kini menghadirkan <strong>Layanan Jemput Zakat</strong> — sebuah inovasi pelayanan zakat, infaq, dan sedekah yang memudahkan masyarakat untuk menunaikan kewajiban tanpa harus datang ke kantor. \r\n      Melalui layanan ini, <em>amil zakat resmi BAZNAS</em> siap datang ke rumah, kantor, atau tempat usaha Anda untuk menjemput zakat sesuai jadwal yang disepakati.\r\n    </p>\r\n    <p>\r\n      Layanan ini dihadirkan sebagai bentuk komitmen BAZNAS untuk memberikan kemudahan, keamanan, dan kenyamanan bagi para <strong>muzaki</strong> (pemberi zakat) dalam berzakat dan berdonasi untuk membantu sesama di Kabupaten Sumbawa.\r\n    </p>\r\n  </section>\r\n\r\n  <section id=\"tujuan\">\r\n    <h2>Tujuan Program</h2>\r\n    <ul>\r\n      <li>Mempermudah masyarakat menunaikan zakat, infaq, dan sedekah.</li>\r\n      <li>Meningkatkan penghimpunan dana ZIS di wilayah Kabupaten Sumbawa.</li>\r\n      <li>Memberikan pelayanan yang cepat, aman, dan profesional.</li>\r\n      <li>Mendorong partisipasi masyarakat dalam program pemberdayaan mustahik.</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <section id=\"cara\">\r\n    <h2>Cara Menggunakan Layanan Jemput Zakat</h2>\r\n    <ol>\r\n      <li>\r\n        <strong>Hubungi Petugas BAZNAS Sumbawa</strong><br>\r\n        ???? Telepon/WhatsApp: <a href=\"https://wa.me/6281936955747\" target=\"_blank\">0819-3695-5747</a><br>\r\n        ???? Jam Layanan: Senin–Jumat, pukul 08.00–16.00 WITA.\r\n      </li>\r\n      <li>\r\n        <strong>Isi Data Muzaki</strong><br>\r\n        Kirimkan data singkat seperti nama lengkap, alamat lokasi jemput, jenis zakat/infaq/sedekah, dan waktu penjemputan yang diinginkan.\r\n      </li>\r\n      <li>\r\n        <strong>Tunggu Konfirmasi Petugas</strong><br>\r\n        Petugas BAZNAS akan menghubungi Anda untuk mengonfirmasi jadwal dan petugas yang ditugaskan.\r\n      </li>\r\n      <li>\r\n        <strong>Penjemputan oleh Amil Resmi</strong><br>\r\n        Petugas BAZNAS datang ke lokasi dengan identitas resmi dan memberikan bukti penerimaan zakat (kwitansi).\r\n      </li>\r\n    </ol>\r\n  </section>\r\n\r\n  <section id=\"jenis\">\r\n    <h2>Jenis Zakat yang Dapat Dijemput</h2>\r\n    <ul>\r\n      <li>Zakat Profesi / Penghasilan</li>\r\n      <li>Zakat Maal (Harta)</li>\r\n      <li>Zakat Fitrah</li>\r\n      <li>Infaq dan Sedekah</li>\r\n      <li>Donasi Program (Mahyani, Beasiswa, Kemanusiaan, Kesehatan, dan lainnya)</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <section id=\"keuntungan\">\r\n    <h2>Keuntungan Menggunakan Layanan Jemput Zakat</h2>\r\n    <ul>\r\n      <li>✅ <strong>Praktis</strong> – tidak perlu datang ke kantor.</li>\r\n      <li>✅ <strong>Aman</strong> – petugas resmi dengan identitas dan surat tugas.</li>\r\n      <li>✅ <strong>Transparan</strong> – setiap zakat tercatat dan mendapat bukti resmi.</li>\r\n      <li>✅ <strong>Berkah</strong> – membantu mustahik di Kabupaten Sumbawa.</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <section id=\"wilayah\">\r\n    <h2>Wilayah Layanan</h2>\r\n    <p>\r\n      Layanan <em>Jemput Zakat</em> BAZNAS Kabupaten Sumbawa tersedia untuk seluruh wilayah, termasuk:\r\n    </p>\r\n    <ul>\r\n      <li>Kecamatan Sumbawa</li>\r\n      <li>Labuhan Badas</li>\r\n      <li>Unter Iwes</li>\r\n      <li>Alas dan Alas Barat</li>\r\n      <li>Lopok</li>\r\n      <li>Moyo Hulu</li>\r\n      <li>Plampang</li>\r\n      <li>Empang</li>\r\n      <li>dan wilayah lainnya di Kabupaten Sumbawa</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <section id=\"kontak\">\r\n    <h2>Kontak dan Informasi</h2>\r\n    <p><strong>BAZNAS Kabupaten Sumbawa</strong><br>\r\n      ???? Jl. Garuda No. 12, Sumbawa Besar, NTB<br>\r\n      ???? <a href=\"https://baznassumbawa.id\" target=\"_blank\">https://baznassumbawa.id</a><br>\r\n      ???? Email:\r\n</p></section></article>', 'layanan jemput zakat', 'Kamis', '2025-10-30', '23:09:47', '6A875F82-A12E-4F2C-AC71-AFBCD144A28D.png', 71, 'berita-dan-kegiatan', 'Y'),
(711, 65, 'admin', 'Gambaran Umum BAZNAS Kabupaten Sumbawa', '', '', 'gambaran-umum-baznas-kabupaten-sumbawa', 'N', 'Y', 'Y', '<article class=\"artikel-profil\">\r\n  <header>\r\n    <h1><span style=\"color: inherit; font-family: inherit; font-size: 2rem;\">Pendahuluan</span></h1></header><section id=\"pendahuluan\">\r\n    <p>\r\n      Badan Amil Zakat Nasional (BAZNAS) Kabupaten Sumbawa merupakan lembaga pemerintah non-struktural yang dibentuk berdasarkan Undang-Undang Nomor 23 Tahun 2011 tentang Pengelolaan Zakat. \r\n      Lembaga ini memiliki tugas dan fungsi untuk mengelola zakat, infaq, dan sedekah (ZIS) secara nasional di tingkat kabupaten dengan prinsip amanah, profesional, transparan, dan akuntabel.\r\n    </p>\r\n    <p>\r\n      BAZNAS Kabupaten Sumbawa hadir sebagai perpanjangan tangan dari BAZNAS Provinsi Nusa Tenggara Barat dalam upaya meningkatkan kesejahteraan masyarakat melalui pengelolaan dana ZIS yang terarah dan tepat sasaran. \r\n      Dalam menjalankan tugasnya, BAZNAS berperan sebagai penghubung antara muzaki (pemberi zakat) dan mustahik (penerima manfaat) agar zakat dapat memberikan dampak sosial yang nyata.\r\n    </p>\r\n  </section>\r\n\r\n  <section id=\"visi-misi\">\r\n    <h2>Visi dan Misi</h2>\r\n    <h3>Visi</h3>\r\n    <p>\r\n      Terwujudnya BAZNAS Kabupaten Sumbawa sebagai lembaga pengelola zakat yang profesional, amanah, dan menjadi pilar utama pengentasan kemiskinan menuju masyarakat Sumbawa yang sejahtera dan berkeadilan.\r\n    </p>\r\n\r\n    <h3>Misi</h3>\r\n    <ul>\r\n      <li>Meningkatkan kesadaran masyarakat dalam menunaikan zakat, infaq, dan sedekah melalui edukasi dan pelayanan prima.</li>\r\n      <li>Mengelola dan menyalurkan dana zakat, infaq, dan sedekah secara efektif, efisien, dan transparan.</li>\r\n      <li>Mendorong kemandirian ekonomi mustahik melalui program pemberdayaan yang berkelanjutan.</li>\r\n      <li>Menjalin sinergi dan kolaborasi dengan pemerintah daerah, lembaga keagamaan, dan sektor swasta dalam upaya peningkatan kesejahteraan masyarakat.</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <section id=\"struktur\">\r\n    <h2>Struktur dan Organisasi</h2>\r\n    <p>\r\n      BAZNAS Kabupaten Sumbawa terdiri dari unsur pimpinan dan pelaksana. Unsur pimpinan bertugas menetapkan kebijakan, mengawasi pelaksanaan pengumpulan dan pendistribusian zakat, serta memastikan terlaksananya tata kelola yang sesuai dengan syariat dan ketentuan peraturan perundang-undangan.\r\n    </p>\r\n    <p>\r\n      Pelaksana BAZNAS bertanggung jawab menjalankan kegiatan operasional, termasuk penghimpunan dana, pendistribusian, pendayagunaan zakat, serta pelaporan keuangan. Seluruh kegiatan BAZNAS dilaksanakan dengan sistem akuntabilitas publik yang terbuka, agar masyarakat dapat memantau setiap proses pengelolaan dana zakat.</p><p><img src=\"http://localhost/blackexpomediaonline/asset/images/Gambar_WhatsApp_2025-10-16_pukul_15_28_12_535a7027.jpg\" style=\"width: 50%;\"><br></p><p>\r\n    </p>\r\n  </section>\r\n\r\n  <section id=\"program\">\r\n    <h2>Program dan Kegiatan</h2>\r\n    <p>\r\n      BAZNAS Kabupaten Sumbawa memiliki sejumlah program unggulan yang berfokus pada lima bidang utama, yaitu:\r\n    </p>\r\n    <ul>\r\n      <li><strong>Sumbawa Makmur</strong> – Program pemberdayaan ekonomi mustahik melalui bantuan modal usaha, pelatihan, dan pendampingan.</li>\r\n      <li><strong>Sumbawa Cerdas</strong> – Program beasiswa pendidikan bagi siswa dan mahasiswa dari keluarga tidak mampu.</li>\r\n      <li><strong>Sumbawa Sehat</strong> – Program bantuan kesehatan bagi masyarakat kurang mampu, termasuk layanan kesehatan gratis dan bantuan obat-obatan.</li>\r\n      <li><strong>Sumbawa Taqwa</strong> – Program peningkatan keimanan dan ketakwaan, termasuk bantuan masjid, kegiatan dakwah, dan pembinaan keagamaan.</li>\r\n      <li><strong>Sumbawa Peduli</strong> – Program tanggap darurat dan kemanusiaan bagi masyarakat terdampak bencana alam atau sosial.</li>\r\n    </ul>\r\n  </section>\r\n\r\n  <section id=\"transparansi\">\r\n    <h2>Transparansi dan Akuntabilitas</h2>\r\n    <p>\r\n      BAZNAS Kabupaten Sumbawa berkomitmen untuk menjaga kepercayaan publik dengan menerapkan sistem pelaporan yang transparan dan akuntabel. \r\n      Setiap dana yang diterima maupun disalurkan dilaporkan secara berkala melalui laporan keuangan dan laporan kegiatan yang dapat diakses oleh masyarakat. \r\n      BAZNAS juga menjalani audit keuangan setiap tahun guna memastikan bahwa seluruh pengelolaan dana sesuai dengan standar akuntansi syariah dan peraturan yang berlaku.\r\n    </p>\r\n  </section>\r\n\r\n  <section id=\"penutup\">\r\n    <h2>Penutup</h2>\r\n    <p>\r\n      Melalui sinergi antara muzaki, pemerintah daerah, dan masyarakat, BAZNAS Kabupaten Sumbawa terus berupaya memperkuat peran zakat sebagai instrumen keadilan sosial dan pemberdayaan ekonomi umat. \r\n      Dengan semangat profesionalisme dan amanah, BAZNAS Sumbawa bertekad untuk menjadi lembaga yang tidak hanya mengelola zakat, tetapi juga menumbuhkan kesadaran berbagi untuk mewujudkan Sumbawa yang lebih sejahtera.\r\n    </p>\r\n  </section>\r\n</article>\r\n', '', 'Kamis', '2025-10-30', '23:20:41', '2192E5E8-4E27-48A9-8D20-4E30ABDE1502.png', 44, 'berita-dan-kegiatan', 'Y'),
(712, 66, 'admin', 'Azaz Pengelolaan BAZNAS Kabupaten Sumbawa', '', '', 'azaz-pengelolaan-baznas-kabupaten-sumbawa', 'N', 'Y', 'Y', '<h2 data-start=\"281\" data-end=\"299\"><strong data-start=\"284\" data-end=\"299\">Pendahuluan</strong></h2><p data-start=\"300\" data-end=\"721\">Badan Amil Zakat Nasional (BAZNAS) Kabupaten Sumbawa merupakan lembaga resmi dan satu-satunya yang dibentuk oleh pemerintah untuk mengelola zakat, infak, dan sedekah (ZIS) di wilayah Kabupaten Sumbawa. Dalam menjalankan tugas dan fungsinya, BAZNAS berpedoman pada prinsip-prinsip pengelolaan yang profesional, transparan, dan akuntabel, sesuai dengan ketentuan Undang-Undang Nomor 23 Tahun 2011 tentang Pengelolaan Zakat.</p><h2 data-start=\"723\" data-end=\"757\"><strong data-start=\"726\" data-end=\"757\">Pengertian Azaz Pengelolaan</strong></h2><p data-start=\"758\" data-end=\"1112\">Azaz pengelolaan zakat adalah landasan atau prinsip dasar yang menjadi acuan BAZNAS dalam melaksanakan kegiatan pengumpulan, pendistribusian, dan pendayagunaan zakat. Prinsip-prinsip ini bertujuan agar pengelolaan zakat dapat berjalan dengan tertib, amanah, serta memberikan manfaat yang optimal bagi mustahik (penerima zakat) dan muzaki (pemberi zakat).</p><h2 data-start=\"1114\" data-end=\"1171\"><strong data-start=\"1117\" data-end=\"1171\">Azaz Pengelolaan Zakat di BAZNAS Kabupaten Sumbawa</strong></h2><ol data-start=\"1173\" data-end=\"2466\">\r\n<li data-start=\"1173\" data-end=\"1405\">\r\n<p data-start=\"1176\" data-end=\"1405\"><strong data-start=\"1176\" data-end=\"1186\">Amanah</strong><br data-start=\"1186\" data-end=\"1189\">\r\nBAZNAS Kabupaten Sumbawa menjalankan tugas pengelolaan zakat dengan penuh tanggung jawab, menjaga kepercayaan muzaki dan masyarakat. Setiap rupiah yang diterima dan disalurkan dipertanggungjawabkan secara terbuka.</p>\r\n</li>\r\n<li data-start=\"1407\" data-end=\"1613\">\r\n<p data-start=\"1410\" data-end=\"1613\"><strong data-start=\"1410\" data-end=\"1426\">Transparansi</strong><br data-start=\"1426\" data-end=\"1429\">\r\nSetiap kegiatan pengumpulan dan pendistribusian zakat dilaporkan secara jelas dan terbuka kepada publik melalui laporan keuangan, publikasi kegiatan, dan media resmi BAZNAS Sumbawa.</p>\r\n</li>\r\n<li data-start=\"1615\" data-end=\"1853\">\r\n<p data-start=\"1618\" data-end=\"1853\"><strong data-start=\"1618\" data-end=\"1637\">Profesionalisme</strong><br data-start=\"1637\" data-end=\"1640\">\r\nPengelolaan zakat dilakukan oleh sumber daya manusia yang kompeten, berintegritas, dan berpengalaman di bidangnya. BAZNAS menerapkan sistem kerja yang efektif dan efisien demi pelayanan terbaik bagi masyarakat.</p>\r\n</li>\r\n<li data-start=\"1855\" data-end=\"2047\">\r\n<p data-start=\"1858\" data-end=\"2047\"><strong data-start=\"1858\" data-end=\"1870\">Keadilan</strong><br data-start=\"1870\" data-end=\"1873\">\r\nPenyaluran dana zakat dilakukan berdasarkan prioritas kebutuhan mustahik, tanpa membeda-bedakan latar belakang, suku, atau golongan, sesuai dengan ketentuan syariat Islam.</p>\r\n</li>\r\n<li data-start=\"2049\" data-end=\"2260\">\r\n<p data-start=\"2052\" data-end=\"2260\"><strong data-start=\"2052\" data-end=\"2073\">Kepatuhan Syariah</strong><br data-start=\"2073\" data-end=\"2076\">\r\nSetiap proses pengumpulan dan penyaluran zakat selalu mengacu pada ketentuan syariah Islam, dengan bimbingan dan pengawasan Dewan Pengawas Syariah (DPS) yang ditetapkan oleh BAZNAS.</p>\r\n</li>\r\n<li data-start=\"2262\" data-end=\"2466\">\r\n<p data-start=\"2265\" data-end=\"2466\"><strong data-start=\"2265\" data-end=\"2282\">Akuntabilitas</strong><br data-start=\"2282\" data-end=\"2285\">\r\nBAZNAS Kabupaten Sumbawa selalu memastikan setiap kegiatan dapat dipertanggungjawabkan baik secara administratif maupun secara moral kepada Allah SWT, pemerintah, dan masyarakat.</p>\r\n</li>\r\n</ol><h2 data-start=\"2468\" data-end=\"2482\"><strong data-start=\"2471\" data-end=\"2482\">Penutup</strong></h2><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p data-start=\"2483\" data-end=\"2711\">Dengan berpegang pada azaz-azaz tersebut, BAZNAS Kabupaten Sumbawa berkomitmen menjadi lembaga pengelola zakat yang terpercaya, profesional, dan memberikan dampak nyata bagi peningkatan kesejahteraan umat di Kabupaten Sumbawa.</p>', '', 'Kamis', '2025-10-30', '23:27:46', '9145097F-AEAE-4D7F-A3CF-8CDD3DD4FB50.png', 64, 'berita-dan-kegiatan', 'Y'),
(713, 68, 'admin', 'Pengertian Unit Pengumpul Zakat (UPZ)', '', '', 'pengertian-unit-pengumpul-zakat-upz', 'N', 'N', 'N', '<p data-start=\"0\" data-end=\"226\"><strong data-start=\"0\" data-end=\"30\">Unit Pengumpul Zakat (UPZ)</strong> adalah satuan organisasi yang dibentuk oleh <strong data-start=\"75\" data-end=\"113\">Badan Amil Zakat Nasional (BAZNAS)</strong> untuk membantu dalam pelaksanaan pengumpulan zakat, infak, dan sedekah (ZIS) di wilayah atau lembaga tertentu.</p><p data-start=\"228\" data-end=\"260\">Berikut penjelasan lengkapnya:</p><hr data-start=\"262\" data-end=\"265\"><h2 data-start=\"267\" data-end=\"288\"><strong data-start=\"270\" data-end=\"288\">Pengertian UPZ</strong></h2><p data-start=\"289\" data-end=\"586\">UPZ merupakan kepanjangan tangan dari BAZNAS di tingkat instansi, lembaga, atau wilayah. Tugas utama UPZ adalah <strong data-start=\"401\" data-end=\"438\">menghimpun zakat dari para muzaki</strong> (pemberi zakat) di lingkungannya masing-masing, seperti kantor pemerintahan, BUMN, masjid, sekolah, perguruan tinggi, hingga desa atau kecamatan.</p><p data-start=\"588\" data-end=\"767\">Setiap dana yang dihimpun oleh UPZ akan <strong data-start=\"628\" data-end=\"667\">disetorkan ke BAZNAS Kabupaten/Kota</strong> untuk dikelola dan didistribusikan sesuai ketentuan syariat Islam dan peraturan perundang-undangan.</p><hr data-start=\"769\" data-end=\"772\"><h2 data-start=\"774\" data-end=\"792\"><strong data-start=\"777\" data-end=\"792\">Dasar Hukum</strong></h2><p data-start=\"793\" data-end=\"827\">Pembentukan UPZ berlandaskan pada:</p><ul data-start=\"828\" data-end=\"995\">\r\n<li data-start=\"828\" data-end=\"895\">\r\n<p data-start=\"830\" data-end=\"895\"><strong data-start=\"830\" data-end=\"867\">Undang-Undang Nomor 23 Tahun 2011</strong> tentang Pengelolaan Zakat</p>\r\n</li>\r\n<li data-start=\"896\" data-end=\"995\">\r\n<p data-start=\"898\" data-end=\"995\"><strong data-start=\"898\" data-end=\"937\">Peraturan BAZNAS Nomor 2 Tahun 2016</strong> tentang Pembentukan dan Tata Kerja Unit Pengumpul Zakat</p>\r\n</li>\r\n</ul><hr data-start=\"997\" data-end=\"1000\"><h2 data-start=\"1002\" data-end=\"1029\"><strong data-start=\"1005\" data-end=\"1029\">Tugas dan Fungsi UPZ</strong></h2><ol data-start=\"1030\" data-end=\"1443\">\r\n<li data-start=\"1030\" data-end=\"1141\">\r\n<p data-start=\"1033\" data-end=\"1141\"><strong data-start=\"1033\" data-end=\"1081\">Mengumpulkan zakat, infak, dan sedekah (ZIS)</strong> dari pegawai, masyarakat, atau instansi di lingkungannya.</p>\r\n</li>\r\n<li data-start=\"1142\" data-end=\"1218\">\r\n<p data-start=\"1145\" data-end=\"1218\"><strong data-start=\"1145\" data-end=\"1182\">Mensosialisasikan kewajiban zakat</strong> dan manfaatnya kepada masyarakat.</p>\r\n</li>\r\n<li data-start=\"1219\" data-end=\"1301\">\r\n<p data-start=\"1222\" data-end=\"1301\"><strong data-start=\"1222\" data-end=\"1261\">Menyetorkan hasil pengumpulan zakat</strong> ke rekening BAZNAS Kabupaten Sumbawa.</p>\r\n</li>\r\n<li data-start=\"1302\" data-end=\"1378\">\r\n<p data-start=\"1305\" data-end=\"1378\"><strong data-start=\"1305\" data-end=\"1346\">Membuat laporan keuangan dan kegiatan</strong> secara berkala kepada BAZNAS.</p>\r\n</li>\r\n<li data-start=\"1379\" data-end=\"1443\">\r\n<p data-start=\"1382\" data-end=\"1443\"><strong data-start=\"1382\" data-end=\"1420\">Membantu verifikasi calon mustahik</strong> di wilayah kerjanya.</p>\r\n</li>\r\n</ol><hr data-start=\"1445\" data-end=\"1448\"><h2 data-start=\"1450\" data-end=\"1479\"><strong data-start=\"1453\" data-end=\"1479\">Tujuan Pembentukan UPZ</strong></h2><ul data-start=\"1480\" data-end=\"1711\">\r\n<li data-start=\"1480\" data-end=\"1551\">\r\n<p data-start=\"1482\" data-end=\"1551\">Meningkatkan <strong data-start=\"1495\" data-end=\"1524\">jangkauan pelayanan zakat</strong> hingga ke tingkat bawah.</p>\r\n</li>\r\n<li data-start=\"1552\" data-end=\"1629\">\r\n<p data-start=\"1554\" data-end=\"1629\">Memudahkan masyarakat untuk <strong data-start=\"1582\" data-end=\"1626\">menunaikan zakat secara resmi dan amanah</strong>.</p>\r\n</li>\r\n<li data-start=\"1630\" data-end=\"1711\">\r\n<p data-start=\"1632\" data-end=\"1711\">Memperkuat peran BAZNAS dalam pemerataan kesejahteraan dan pemberdayaan umat.</p>\r\n</li>\r\n</ul><hr data-start=\"1713\" data-end=\"1716\"><h2 data-start=\"1718\" data-end=\"1756\"><strong data-start=\"1721\" data-end=\"1756\">Contoh UPZ di Kabupaten Sumbawa</strong></h2><ul data-start=\"1757\" data-end=\"1881\">\r\n<li data-start=\"1757\" data-end=\"1797\">\r\n<p data-start=\"1759\" data-end=\"1797\">UPZ Kantor Dinas/Instansi Pemerintah</p>\r\n</li>\r\n<li data-start=\"1798\" data-end=\"1822\">\r\n<p data-start=\"1800\" data-end=\"1822\">UPZ Sekolah/Madrasah</p>\r\n</li>\r\n<li data-start=\"1823\" data-end=\"1853\">\r\n<p data-start=\"1825\" data-end=\"1853\">UPZ Masjid Besar Kecamatan</p>\r\n</li>\r\n<li data-start=\"1854\" data-end=\"1881\">\r\n<p data-start=\"1856\" data-end=\"1881\">UPZ Desa atau Kelurahan</p>\r\n</li>\r\n</ul><hr data-start=\"1883\" data-end=\"1886\"><h2 data-start=\"1888\" data-end=\"1905\"><strong data-start=\"1891\" data-end=\"1905\">Kesimpulan</strong></h2><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p data-start=\"1906\" data-end=\"2206\">Unit Pengumpul Zakat (UPZ) adalah mitra strategis BAZNAS Kabupaten Sumbawa dalam memastikan pengumpulan zakat berjalan efektif, transparan, dan tepat sasaran. Dengan adanya UPZ, masyarakat semakin mudah menunaikan zakat, serta potensi zakat di daerah dapat dioptimalkan untuk kesejahteraan bersama.</p>', '', 'Jumat', '2025-10-31', '08:58:23', 'UPZ1.jpg', 57, 'berita-dan-kegiatan', 'Y'),
(717, 65, 'admin', 'Tugas dan Fungsi Bidang P2-AMU Perencanaan & Pelaporan, Administrasi, SDM dan Umum', '', '', 'tugas-dan-fungsi-bidang-p2amu-perencanaan--pelaporan-administrasi-sdm-dan-umum', 'Y', 'N', 'N', '<p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n2\"><b><span style=\"font-family:\"Cambria\",serif;mso-fareast-font-family:\"Times New Roman\";\r\nmso-bidi-font-family:Cambria\">Bidang “</span></b><b><span style=\"font-family:\r\n\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\nmso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">P2-AMU</span></b><b><span style=\"font-family:\"Cambria\",serif;mso-fareast-font-family:\"Times New Roman\";\r\nmso-bidi-font-family:Cambria\">”</span></b><b><span style=\"font-family:\"Cambria\",serif;\r\nmso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\nmso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\"> </span></b><i><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">(Perencanaan\r\n& Pelaporan, Administrasi, Manusia (SDM), Umum).</span></i><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">\r\n<o:p></o:p></span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><span style=\"font-size:8.0pt;font-family:\"Cambria\",serif;mso-ascii-theme-font:\r\nmajor-latin;mso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:\r\nmajor-latin;mso-bidi-font-family:\"Times New Roman\"\"> </span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Kepala Bidang (Kabid)</span></b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">\r\n          </span>        <span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\"> </span>    <span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\"> : Zulfa Azizah, A.Md<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Anggota                                             </span>    <span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">  : Riky Anggara, S.Kom<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">                                                                : M.Tezar Hairullah, S.Ak<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">                                                                : Yosi Harianto, S.Pd<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">                                                                : Adeliah<b>, </b>S.M    <b><o:p></o:p></b></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-size:8.0pt;font-family:\"Cambria\",serif;mso-ascii-theme-font:\r\nmajor-latin;mso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:\r\nmajor-latin;mso-bidi-font-family:\"Times New Roman\"\"> </span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Tugas Pokok:<o:p></o:p></span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Melaksanakan\r\nperencanaan program dan anggaran, pengelolaan keuangan, serta penyusunan\r\nlaporan keuangan dan pertanggungjawaban lembaga sesuai dengan ketentuan yang\r\nberlaku.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Fungsi:<o:p></o:p></span></b></p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l3 level1 lfo1;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menyusun\r\n     rencana kerja dan anggaran tahunan lembaga (RKAT).<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l3 level1 lfo1;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Mengelola\r\n     penerimaan dan pengeluaran keuangan secara tertib dan transparan.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l3 level1 lfo1;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menyusun\r\n     laporan keuangan berkala (bulanan, triwulan, tahunan).<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l3 level1 lfo1;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Melakukan\r\n     pengendalian dan evaluasi pelaksanaan anggaran.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l3 level1 lfo1;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menyiapkan\r\n     bahan audit dan pertanggungjawaban keuangan.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l3 level1 lfo1;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menjamin\r\n     kepatuhan terhadap standar akuntansi dan regulasi keuangan lembaga.<o:p></o:p></span></li>\r\n</ul><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\"> </span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n2\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">2. Bidang Administrasi (ADM)<o:p></o:p></span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Tugas Pokok:<o:p></o:p></span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Mengelola\r\nadministrasi kesekretariatan, surat-menyurat, arsip, dan dokumentasi kegiatan\r\nlembaga agar tertata dengan baik dan mudah diakses.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Fungsi:<o:p></o:p></span></b></p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l1 level1 lfo2;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Mengatur\r\n     surat masuk dan surat keluar lembaga.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l1 level1 lfo2;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menyusun\r\n     dan memelihara arsip dokumen penting.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l1 level1 lfo2;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menyusun\r\n     notulen rapat, laporan administrasi, dan dokumentasi kegiatan.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l1 level1 lfo2;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menyediakan\r\n     pelayanan administrasi untuk seluruh bidang.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l1 level1 lfo2;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Mengelola\r\n     data dan informasi kelembagaan secara tertib.<o:p></o:p></span></li>\r\n</ul><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\"> </span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">3.\r\nBidang Sumber Daya Manusia (SDM)</span></b><span style=\"font-family:\"Cambria\",serif;\r\nmso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\nmso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Tugas Pokok:<o:p></o:p></span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Melaksanakan\r\npengelolaan, pengembangan, dan pembinaan SDM guna mendukung kinerja lembaga\r\nsecara optimal.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Fungsi:<o:p></o:p></span></b></p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l0 level1 lfo3;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Melakukan\r\n     perencanaan kebutuhan tenaga kerja dan rekrutmen.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l0 level1 lfo3;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menyelenggarakan\r\n     pelatihan, pembinaan, dan peningkatan kompetensi pegawai.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l0 level1 lfo3;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Mengelola\r\n     data kepegawaian, absensi, dan kinerja staf.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l0 level1 lfo3;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menyusun\r\n     sistem penilaian, penghargaan, dan disiplin pegawai.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l0 level1 lfo3;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Membina\r\n     hubungan kerja yang harmonis antarpegawai.<o:p></o:p></span></li>\r\n</ul><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\"> </span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">4.\r\nBidang Umum</span></b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:\r\nmajor-latin;mso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:\r\nmajor-latin;mso-bidi-font-family:\"Times New Roman\"\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Tugas Pokok:<o:p></o:p></span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;mso-fareast-font-family:\r\n\"Times New Roman\";mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Memberikan\r\ndukungan operasional umum bagi kelancaran seluruh kegiatan lembaga, termasuk\r\npengelolaan aset, logistik, sarana-prasarana, dan kebersihan.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-outline-level:\r\n3\"><b><span style=\"font-family:\"Cambria\",serif;mso-ascii-theme-font:major-latin;\r\nmso-fareast-font-family:\"Times New Roman\";mso-hansi-theme-font:major-latin;\r\nmso-bidi-font-family:\"Times New Roman\"\">Fungsi:<o:p></o:p></span></b></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;mso-outline-level:2\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l2 level1 lfo4;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Mengelola\r\n     penggunaan, perawatan, dan inventarisasi aset kantor.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l2 level1 lfo4;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menangani\r\n     kebutuhan logistik, perlengkapan, dan konsumsi kegiatan.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l2 level1 lfo4;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Menjaga\r\n     kebersihan, keamanan, dan kenyamanan lingkungan kerja.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l2 level1 lfo4;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Mengatur\r\n     transportasi dan operasional kendaraan dinas.<o:p></o:p></span></li>\r\n <li class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal;mso-list:l2 level1 lfo4;\r\n     tab-stops:list 36.0pt\"><span style=\"font-family:\"Cambria\",serif;\r\n     mso-ascii-theme-font:major-latin;mso-fareast-font-family:\"Times New Roman\";\r\n     mso-hansi-theme-font:major-latin;mso-bidi-font-family:\"Times New Roman\"\">Membantu\r\n     kelancaran pelaksanaan kegiatan internal dan eksternal lembaga.<o:p></o:p></span></li>\r\n</ul><ul style=\"margin-top:0cm\" type=\"disc\">\r\n</ul>', '', 'Senin', '2025-11-03', '07:39:47', '1.jpg', 117, 'berita-dan-kegiatan', 'Y');
